def seed_rbac_catalog(apps, schema_editor):
    """Cria Permissions, Roles, Matriz Role×Permission e JobTitles do catálogo global."""
    Permission = apps.get_model('core', 'Permission')
    Role = apps.get_model('core', 'Role')
    JobTitle = apps.get_model('core', 'JobTitle')

    print('')

    # 1. Permissões
    perm_objs = {}
    for slug, desc in PERMISSIONS:
        obj, created = Permission.objects.update_or_create(
            slug=slug, defaults={'name': slug, 'description': desc}
        )
        perm_objs[slug] = obj
        if created:
            print(f"  -> Permissão '{slug}' criada.")
    print(f"  -> Total de permissões: {len(perm_objs)}")

    # 2. Roles
    role_objs = {}
    for slug, name, scope, level, inheritance in ROLES:
        obj, created = Role.objects.update_or_create(
            slug=slug,
            defaults={
                'name': name, 'scope': scope, 'level': level,
                'inheritance': inheritance, 'is_system_role': True,
            }
        )
        role_objs[slug] = obj
        if created:
            print(f"  -> Role '{slug}' ({scope}) criada.")
    print(f"  -> Total de roles: {len(role_objs)}")

    # 3. Matriz Role × Permission
    for role_slug, perm_slugs in ROLE_PERMISSIONS.items():
        role = role_objs.get(role_slug)
        if not role:
            continue
        if perm_slugs == ['*']:
            role.permissions.set(perm_objs.values())
        else:
            role.permissions.set([perm_objs[s] for s in perm_slugs if s in perm_objs])
        print(f"  -> {role_slug}: {role.permissions.count()} permissões atribuídas.")

    # 4. JobTitles (catálogo global: organization=NULL)
    for slug, name, level, category in JOB_TITLES:
        _, created = JobTitle.objects.update_or_create(
            slug=slug, organization=None,
            defaults={'name': name, 'level': level, 'category': category, 'is_system': True}
        )
        if created:
            print(f"  -> JobTitle '{slug}' ({level}/{category}) criado.")
    print(f"  -> Total de cargos globais: {len(JOB_TITLES)}")


def remove_rbac_catalog(apps, schema_editor):
    Permission = apps.get_model('core', 'Permission')
    Role = apps.get_model('core', 'Role')
    JobTitle = apps.get_model('core', 'JobTitle')
    slugs = [s for s, _ in PERMISSIONS]
    Permission.objects.filter(slug__in=slugs).delete()
    Role.objects.filter(slug__in=[s for s, *_ in ROLES]).delete()
    JobTitle.objects.filter(organization__isnull=True, is_system=True).delete()


